// Purpose: Use the same authenticated workspace APIs for policy editing, bounded evaluations and explicit report sharing.
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let workspace={policies:[],reports:[]},report,authenticated=false;
async function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{'content-type':'application/json'},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(90000)});const data=await r.json();if(!r.ok)throw Error(data.error);return data;}
async function run(fn){$('#error').textContent='';document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();}catch(e){$('#error').textContent=e.message;}finally{document.querySelectorAll('button').forEach(b=>b.disabled=false);}}
function download(name,data){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function showReport(value){report=value;$('#report').hidden=false;$('#report-summary').textContent=(value.mode==='live'?'Jev':'Simulation')+' · '+value.rows.length+' résultat(s)';$('#report-data').textContent=JSON.stringify(value.rows,null,2);$('#report-rows').innerHTML=value.rows.map((r,i)=>`<details><summary class="row"><span>◈</span><strong>Ligne ${i+1} · ${esc(r.record?.outcome??'Erreur')}</strong><span>${esc(r.status==='succeeded'?r.record.latencyMs+' ms':r.error)}</span></summary><pre>${esc(JSON.stringify(r.state,null,2))}</pre></details>`).join('');$('#share-result').replaceChildren();}
async function refresh(selectId){if(!authenticated)return;workspace=await api('workspace');$('#policies').innerHTML=workspace.policies.map(p=>`<option value="${esc(p.id)}">${esc(p.pack.name)} · ${esc(p.pack.version)}</option>`).join('');if(selectId)$('#policies').value=selectId;$('#report-items').innerHTML=workspace.reports.map(r=>`<button data-report="${esc(r.id)}">${esc(r.policy)} · ${esc(r.version)} · ${r.count} lignes · ${r.mode==='live'?'Jev':'Simulation'} <time>${esc(new Date(r.created).toLocaleString('fr'))}</time></button>`).join('')||'<p>Aucun rapport enregistré.</p>';}
$('#policies').onchange=()=>{const p=workspace.policies.find(p=>p.id===$('#policies').value);if(p)$('#policy').value=JSON.stringify(p.pack,null,2);};
$('#demo').onclick=()=>run(async()=>{const d=await api('demo');$('#policy').value=JSON.stringify(d.pack,null,2);showReport(d.report);});
$('#save').onclick=()=>run(async()=>{const p=await api('policies',{pack:JSON.parse($('#policy').value)});await refresh(p.id);});
$('#upload').onchange=()=>run(async()=>{const f=$('#upload').files[0];if(!f||f.size>100000)throw Error('JSON de moins de 100 Ko requis');const data=JSON.parse(await f.text());if(!Array.isArray(data)||!data.length||data.length>10)throw Error('Importez un tableau de 1 à 10 états');$('#states').value=JSON.stringify(data,null,2);});
$('#evaluate').onclick=()=>run(async()=>{const p=await api('policies',{pack:JSON.parse($('#policy').value)});let result;try{result=await api('evaluations',{policyId:p.id,states:JSON.parse($('#states').value),mode:$('#mode').value,apiKey:$('#api-key').value});}finally{$('#api-key').value='';}showReport(result);await refresh(p.id);});
$('#report-items').onclick=e=>run(async()=>{const b=e.target.closest('[data-report]');if(b)showReport(await api('report/'+b.dataset.report));});
$('#download-pack').onclick=()=>run(async()=>download('decision-pack.json',JSON.parse($('#policy').value)));
$('#download').onclick=()=>run(async()=>{if(!report)throw Error('Ouvrez un rapport');download('decision-report.json',report);});
$('#share').onclick=()=>run(async()=>{if(!report?.id)throw Error('Enregistrez une évaluation avant de la partager');const share=await api('share',{reportId:report.id});$('#share-result').innerHTML=`<a href="${esc(share.url)}" target="_blank" rel="noreferrer">Ouvrir la synthèse</a><label>Lien de synthèse<input readonly value="${esc(share.url)}"></label><button id="revoke">Révoquer ce lien</button>`;$('#revoke').onclick=()=>run(async()=>{await api('share/revoke',{id:share.id});$('#share-result').textContent='Lien révoqué.';});});
run(async()=>{const me=await api('me');authenticated=me.authenticated;$('#identity').textContent=authenticated?(me.email??'Espace personnel'):'Démonstration';$('#signin').textContent=authenticated?'Se déconnecter':'Se connecter';if(authenticated)$('#signin').href='/signout-with-chatgpt?return_to=%2F';const sharing=new URLSearchParams(location.search).get('share');if(sharing){const summary=await api('shared/'+encodeURIComponent(sharing));$('#report').hidden=false;$('#report-summary').textContent='Synthèse partagée · '+summary.mode;$('#report-data').textContent=JSON.stringify(summary,null,2);$('#download').hidden=true;$('#share').hidden=true;}await refresh();if(!$('#policy').value){const saved=workspace.policies.find(p=>p.id===$('#policies').value);const pack=saved?.pack??(await api('demo')).pack;$('#policy').value=JSON.stringify(pack,null,2);}});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();addEventListener('pagehide',()=>lifecycle.abort(),{once:true});Promise.resolve(document.modelContext.registerTool({name:'read_decision_workspace',description:'List the signed-in user’s saved policies and report summaries.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object');await refresh();return workspace;}},{signal:lifecycle.signal})).catch(e=>{$('#error').textContent='Agent workspace tool unavailable: '+e.message;});}
